// The agent sends: card_a, value_a, card_b, value_b, stat
// Quartet rule: the higher value wins, except acceleration and consumption (lower wins).
const LOWER_WINS = ['acc_0_100_s', 'consumption_kwh_100km'];
const UNITS = {
  range_km: 'km', acc_0_100_s: 's', top_speed_kmh: 'km/h',
  battery_kwh: 'kWh', consumption_kwh_100km: 'kWh/100 km',
};

const stat = String(query.stat).trim();
if (!(stat in UNITS)) {
  return `Unknown stat "${stat}". Use one of: ${Object.keys(UNITS).join(', ')}.`;
}
const a = Number(query.value_a);
const b = Number(query.value_b);
if (Number.isNaN(a) || Number.isNaN(b)) {
  return 'value_a and value_b must be numbers from the database.';
}

const lowerWins = LOWER_WINS.includes(stat);
let winner = 'tie';
if (a !== b) {
  const aWins = lowerWins ? a < b : a > b;
  winner = aWins ? query.card_a : query.card_b;
}

return JSON.stringify({
  stat,
  unit: UNITS[stat],
  rule: lowerWins ? 'lower wins' : 'higher wins',
  [query.card_a]: a,
  [query.card_b]: b,
  winner,
  difference: Math.round(Math.abs(a - b) * 100) / 100,
});

