// The agent sends: battery_kwh, range_km
// Consumption = battery / range * 100  (kWh per 100 km)
const battery = Number(query.battery_kwh);
const range = Number(query.range_km);
if (!(battery > 0) || !(range > 0)) {
  return 'battery_kwh and range_km must be numbers greater than 0.';
}
const perHundred = Math.round((battery / range) * 100 * 100) / 100;
return JSON.stringify({
  battery_kwh: battery,
  range_km: range,
  kwh_per_100km: perHundred,
});

